# 0085: قسم الاتفاقيات — قوالب الاتفاقيات وملاحقها (agr_templates) والاتفاقيات (agreements). المحتوى في content.py
import json, os, sys
sys.path.insert(0, os.path.dirname(__file__))
from content import AGREEMENT, ANNEX, PHASES, BUDGET, MED
ROOT = os.path.join(os.path.dirname(__file__), '..', '..')
def q(s): return "$t$" + s + "$t$"
body = {"agreement": AGREEMENT, "annex": ANNEX, "phases": PHASES, "budget": BUDGET, "med": MED}
defaults = {"affil": "شركة الصحة القابضة", "p1_rep": "الدكتور خالد بن محمد الملا", "p1_rep_title": "الرئيس التنفيذي", "months": 36,
            "naming": True, "annex": True, "v2": True, "cameras": True, "fm": 3, "dent": 2, "med": ["علامات حيوية", "تطعيم", "منطقة عناية حرجة"], "floors": 1}
o = ["-- 0085: قسم الاتفاقيات — قالب «اتفاقية شراكة مجتمعية لإنشاء وتجهيز مركز رعاية صحية أولية» (صيغة مايو 2026) وملحق إجراءات وآليات العمل، وجدول الاتفاقيات. المولّد tools/agreements/mk85.py",
"""create table if not exists public.agr_templates (
  code text primary key, title text not null, ver text not null default '', body jsonb not null default '{}', defaults jsonb not null default '{}',
  active boolean not null default true, updated_at timestamptz not null default now());
create table if not exists public.agreements (
  id uuid primary key default gen_random_uuid(), no int generated by default as identity, tpl text not null references public.agr_templates(code),
  title text not null default '', donor text not null default '', amount numeric, status text not null default 'draft',
  data jsonb not null default '{}', project_id uuid references public.projects(id) on delete set null,
  created_by uuid default auth.uid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), signed_at date,
  log jsonb not null default '[]');
alter table public.agr_templates enable row level security;
alter table public.agreements enable row level security;
drop policy if exists p_read on public.agr_templates; create policy p_read on public.agr_templates for select using (public.can_read());
drop policy if exists p_admin on public.agr_templates; create policy p_admin on public.agr_templates for all using (public.is_admin()) with check (public.is_admin());
drop policy if exists p_read on public.agreements; create policy p_read on public.agreements for select using (public.can_read());
drop policy if exists p_ins on public.agreements; create policy p_ins on public.agreements for insert with check (public.is_admin() or public.can_edit());
drop policy if exists p_upd on public.agreements; create policy p_upd on public.agreements for update using (public.is_admin() or public.can_edit()) with check (public.is_admin() or public.can_edit());
drop policy if exists p_del on public.agreements; create policy p_del on public.agreements for delete using (public.is_admin());
grant select on public.agr_templates to authenticated; grant insert, update, delete on public.agr_templates to authenticated;
grant select, insert, update, delete on public.agreements to authenticated;"""]
o.append(f"insert into public.agr_templates (code, title, ver, body, defaults) values ('PA-PHC', {q('اتفاقية شراكة مجتمعية — إنشاء وتجهيز مركز رعاية صحية أولية')}, {q('صيغة مايو 2026')}, {q(json.dumps(body, ensure_ascii=False))}::jsonb, {q(json.dumps(defaults, ensure_ascii=False))}::jsonb)\n  on conflict (code) do nothing;")
open(os.path.join(ROOT, 'supabase', 'migrations', '0085_agreements.sql'), 'w').write('\n'.join(o) + '\n')
